class AtlasError(Exception):
    pass


def runtime_dir():
    folder = os.path.join(DATA_ROOT, "runtime-" + PAYLOAD_ID)
    exe = os.path.join(folder, "msdfgen.exe")
    lib = os.path.join(folder, "fonttools.zip")
    if not (os.path.isfile(exe) and os.path.isfile(lib)):
        os.makedirs(folder, exist_ok=True)
        for path, blob in ((exe, MSDFGEN_B64), (lib, FONTTOOLS_B64)):
            data = lzma.decompress(base64.b64decode("".join(blob.split())))
            tmp = path + ".tmp"
            with open(tmp, "wb") as f:
                f.write(data)
            os.replace(tmp, path)
    if lib not in sys.path:
        sys.path.insert(0, lib)
    return folder


def msdfgen_path():
    return os.path.join(runtime_dir(), "msdfgen.exe")


def open_font(path, face=0):
    runtime_dir()
    from fontTools.ttLib import TTFont
    if path.lower().endswith((".ttc", ".otc")):
        return TTFont(path, fontNumber=face or 0)
    return TTFont(path)


def font_faces(path):
    runtime_dir()
    from fontTools.ttLib import TTCollection, TTFont
    if path.lower().endswith((".ttc", ".otc")):
        return [display_name(f) for f in TTCollection(path).fonts]
    return [display_name(TTFont(path, lazy=True))]


def display_name(font):
    names = font["name"]
    full = names.getDebugName(4)
    if full:
        return full
    return " ".join(x for x in (names.getDebugName(1), names.getDebugName(2)) if x)


def font_styles(path, face=0):
    font = open_font(path, face)
    if "fvar" not in font:
        return []
    names = font["name"]
    return [(names.getDebugName(i.subfamilyNameID) or str(i.coordinates), dict(i.coordinates))
            for i in font["fvar"].instances]


def missing_glyphs(path, face=0):
    cmap = open_font(path, face).getBestCmap() or {}
    return [c for c in GLYPHS if c != " " and ord(c) not in cmap]


def substitutes(missing):
    return {c: c.upper() for c in missing if c.islower() and c.upper() not in missing}


def suggested_asset_name(path, face=0, style=None):
    font = open_font(path, face)
    base = font["name"].getDebugName(1) or os.path.splitext(os.path.basename(path))[0]
    sub = style or font["name"].getDebugName(2) or ""
    if sub.lower() in ("regular", "normal"):
        sub = ""
    return "Text_Atlas_MSDF_" + re.sub(r"[^A-Za-z0-9_]", "", (base + sub).replace(" ", ""))


def static_font(path, face, style, workdir):
    font = open_font(path, face)
    is_collection = path.lower().endswith((".ttc", ".otc"))
    variable = "fvar" in font
    if not is_collection and not variable:
        return path
    if variable:
        from fontTools.varLib import instancer
        coords = {a.axisTag: a.defaultValue for a in font["fvar"].axes}
        if style:
            match = [c for n, c in font_styles(path, face) if n == style]
            if not match:
                raise AtlasError(f"Style '{style}' was not found in the font.")
            coords.update(match[0])
        font = instancer.instantiateVariableFont(font, coords)
    out = os.path.join(workdir, "static_font.ttf")
    font.save(out)
    return out


def run_msdfgen(args):
    result = subprocess.run([msdfgen_path()] + args, capture_output=True, text=True, creationflags=NO_WINDOW)
    if result.returncode != 0:
        raise AtlasError("msdfgen failed: " + (result.stderr.strip() or result.stdout.strip()))
    return result.stdout


def glyph_bounds(font, ch):
    out = run_msdfgen(["metrics", "-font", font, hex(ord(ch)), "-emnormalize", "-printmetrics"])
    m = re.search(r"bounds = ([-\d.e]+), ([-\d.e]+), ([-\d.e]+), ([-\d.e]+)", out)
    return tuple(float(v) for v in m.groups()) if m else None


def glyph_advance(font, ch):
    out = run_msdfgen(["metrics", "-font", font, hex(ord(ch)), "-emnormalize", "-printmetrics"])
    m = re.search(r"advance = ([-\d.e]+)", out)
    return float(m.group(1)) if m else None


def measure_widths(atlas, space_width):
    ink = re.compile(rb"[\x80-\xff]")
    widths = []
    for index in range(GRID * GRID):
        row, col = divmod(index, GRID)
        x0, x1 = round(col * CELL), round((col + 1) * CELL)
        y0, y1 = round(row * CELL), round((row + 1) * CELL)
        left = right = None
        if index != CODE_SPACE:
            for y in range(y0, y1):
                base = y * SIZE * 4
                alphas = bytes(atlas[base + x0 * 4 + 3:base + x1 * 4:4])
                first = ink.search(alphas)
                if first:
                    last = len(alphas) - 1 - ink.search(alphas[::-1]).start()
                    left = first.start() if left is None else min(left, first.start())
                    right = last if right is None else max(right, last)
        widths.append(round(space_width if left is None else (right - left + 1) / (x1 - x0), 4))
    return widths


def render_cell(font, ch, scale, index, workdir):
    row, col = divmod(index, GRID)
    x0, x1 = round(col * CELL), round((col + 1) * CELL)
    y0, y1 = round(row * CELL), round((row + 1) * CELL)
    w, h = x1 - x0, y1 - y0
    bounds = glyph_bounds(font, ch)
    if bounds is None:
        return None
    left, _, right, _ = bounds
    tx = ((col + 0.5) * CELL - x0) / scale - (left + right) / 2
    ty = (h - (row * CELL + BASELINE - y0)) / scale
    path = os.path.join(workdir, f"g{index}.rgba")
    run_msdfgen(["mtsdf", "-font", font, hex(ord(ch)), "-emnormalize",
                 "-scale", repr(scale), "-translate", repr(tx), repr(ty),
                 "-dimensions", str(w), str(h), "-pxrange", repr(SPREAD),
                 "-scanline", "-format", "rgba", "-o", path])
    raw = open(path, "rb").read()
    if raw[:4] != b"RGBA":
        raise AtlasError("Unexpected msdfgen output.")
    rw, rh = struct.unpack(">II", raw[4:12])
    return x0, y0, rw, rh, raw[12:]


def png_chunk(tag, body):
    data = tag + body
    return struct.pack(">I", len(body)) + data + struct.pack(">I", zlib.crc32(data) & 0xFFFFFFFF)


def write_png(path, width, height, pixels, channels=4):
    stride = width * channels
    rows = b"".join(b"\x00" + bytes(pixels[y * stride:(y + 1) * stride]) for y in range(height))
    color_type = 6 if channels == 4 else 2
    with open(path, "wb") as f:
        f.write(b"\x89PNG\r\n\x1a\n")
        f.write(png_chunk(b"IHDR", struct.pack(">IIBBBBB", width, height, 8, color_type, 0, 0, 0)))
        f.write(png_chunk(b"IDAT", zlib.compress(rows, 6)))
        f.write(png_chunk(b"IEND", b""))


def analyze(atlas):
    far = int(255 * (0.5 - 3 / SPREAD))
    outline = int(255 * (0.5 - OUTLINE_SIZE))
    wx0, wx1 = (0.5 - FIT_X / 2) * CELL, (0.5 + FIT_X / 2) * CELL
    wy0, wy1 = TOP_Y * CELL, (TOP_Y + FIT_Y) * CELL
    stray = 0
    clipped = []
    for index, ch in enumerate(GLYPHS):
        if ch == " ":
            continue
        row, col = divmod(index, GRID)
        x0, x1 = round(col * CELL), round((col + 1) * CELL)
        y0, y1 = round(row * CELL), round((row + 1) * CELL)
        left = top = 10 ** 9
        right = bottom = -1
        for y in range(y0, y1):
            base = y * SIZE * 4
            line = atlas[base + x0 * 4: base + x1 * 4]
            alphas = line[3::4]
            if max(alphas) <= outline:
                continue
            for i, a in enumerate(alphas):
                if a > outline:
                    left = min(left, i)
                    right = max(right, i)
                    top = min(top, y - y0)
                    bottom = y - y0
                if a < far:
                    p = i * 4
                    r, g, b = line[p], line[p + 1], line[p + 2]
                    if max(min(r, g), min(max(r, g), b)) > 127:
                        stray += 1
        if right < 0:
            clipped.append((ch, None))
            continue
        margin = min(left - wx0, wx1 - right, top - wy0, wy1 - bottom)
        if margin < 0:
            clipped.append((ch, int(round(-margin))))
    return stray, clipped


PREVIEW_SIZE = 440


def make_preview(atlas, size=PREVIEW_SIZE):
    outline = int(255 * (0.5 - OUTLINE_SIZE))
    out = bytearray(size * size * 3)
    columns = [int((x + 0.5) * SIZE / size) * 4 for x in range(size)]
    for y in range(size):
        src_row = int((y + 0.5) * SIZE / size) * SIZE * 4
        dst_row = y * size * 3
        for x in range(size):
            p = src_row + columns[x]
            r, g, b, a = atlas[p], atlas[p + 1], atlas[p + 2], atlas[p + 3]
            d = dst_row + x * 3
            if max(min(r, g), min(max(r, g), b)) > 127:
                out[d:d + 3] = b"\xff\xd2\x3c"
            elif a > outline:
                out[d:d + 3] = b"\x0b\x0c\x10"
            else:
                out[d:d + 3] = b"\x23\x25\x2c"
    return out


def generate_atlas(font_path, png_path, face=0, style=None, progress=None, preview_path=None):
    report = progress or (lambda fraction, text: None)
    report(0.01, "Unpacking runtime")
    runtime_dir()
    missing = missing_glyphs(font_path, face)
    if "H" in missing:
        raise AtlasError("The font has no 'H', which defines the letter size.")
    subs = substitutes(missing)
    missing = [c for c in missing if c not in subs]
    with tempfile.TemporaryDirectory() as workdir:
        report(0.03, "Preparing font")
        font = static_font(font_path, face, style, workdir)
        scale = CAP_HEIGHT / glyph_bounds(font, "H")[3]
        space_advance = glyph_advance(font, " ")
        space_width = space_advance * scale / CELL if space_advance else FALLBACK_SPACE
        atlas = bytearray(SIZE * SIZE * 4)
        jobs = [(i, subs.get(c, c)) for i, c in enumerate(GLYPHS) if c != " " and c not in missing]
        done = 0
        with concurrent.futures.ThreadPoolExecutor(max_workers=8) as pool:
            futures = [pool.submit(render_cell, font, c, scale, i, workdir) for i, c in jobs]
            for future in concurrent.futures.as_completed(futures):
                cell = future.result()
                done += 1
                report(0.05 + 0.55 * done / len(jobs), f"Rendering glyph {done} of {len(jobs)}")
                if cell is None:
                    continue
                x0, y0, w, h, px = cell
                for y in range(h):
                    dst = ((y0 + y) * SIZE + x0) * 4
                    atlas[dst:dst + w * 4] = px[y * w * 4:(y + 1) * w * 4]
        widest_char, widest = "", 0.0
        for c in GLYPHS:
            if c == " " or c in missing:
                continue
            b = glyph_bounds(font, subs.get(c, c))
            if b and (b[2] - b[0]) * scale > widest:
                widest_char, widest = c, (b[2] - b[0]) * scale
    report(0.65, "Checking the atlas")
    stray, clipped = analyze(atlas)
    report(0.75, "Measuring glyph widths")
    widths = measure_widths(atlas, space_width)
    report(0.85, "Writing PNG")
    os.makedirs(os.path.dirname(os.path.abspath(png_path)), exist_ok=True)
    write_png(png_path, SIZE, SIZE, atlas)
    if preview_path:
        write_png(preview_path, PREVIEW_SIZE, PREVIEW_SIZE, make_preview(atlas), channels=3)
    report(1.0, "Done")
    return {"png": os.path.abspath(png_path), "scale": scale, "missing": missing, "substituted": sorted(subs),
            "widest": widest_char, "side_margin": (CELL - widest) / 2, "stray": stray, "clipped": clipped,
            "widths": widths}


def content_browser_folder():
    try:
        path = str(unreal.EditorUtilityLibrary.get_current_content_browser_path() or "")
    except Exception:
        return ""
    return path[4:] if path.startswith("/All/") else path


def normalize_folder(path):
    parts = [p for p in str(path or "").replace("\\", "/").split("/") if p]
    return "/" + "/".join(parts) if parts else ""


def project_root(hint=""):
    for candidate in (content_browser_folder(), hint):
        folder = normalize_folder(candidate)
        if folder:
            return "/" + folder.split("/")[1]
    return "/Game"


def list_folders(path, hint=""):
    root = project_root(hint or path)
    folder = normalize_folder(path) or root
    if not folder.startswith(root) or not unreal.EditorAssetLibrary.does_directory_exist(folder):
        folder = root
    names = set()
    try:
        for item in unreal.EditorAssetLibrary.list_assets(folder, recursive=False, include_folder=True):
            text = str(item)
            if text.endswith("/"):
                names.add(normalize_folder(text))
    except Exception:
        pass
    if not names:
        try:
            registry = unreal.AssetRegistryHelpers.get_asset_registry()
            for sub in registry.get_sub_paths(folder, False):
                names.add(normalize_folder(sub))
        except Exception:
            pass
    names.discard(folder)
    return {"path": folder, "root": root, "folders": sorted(names, key=str.lower)}


def make_folder(path):
    folder = normalize_folder(path)
    if not folder:
        raise AtlasError("Invalid folder name.")
    if not unreal.EditorAssetLibrary.does_directory_exist(folder):
        if not unreal.EditorAssetLibrary.make_directory(folder):
            raise AtlasError(f"Could not create {folder}.")
    return folder


def import_texture(png, folder, name, replace, widths=None):
    folder = "/" + folder.strip().strip("/")
    asset_path = f"{folder}/{name}"
    if not os.path.isfile(png):
        raise AtlasError(f"PNG not found: {png}")
    if unreal.EditorAssetLibrary.does_asset_exist(asset_path) and not replace:
        raise AtlasError(f"{asset_path} already exists. Enable 'Replace existing asset'.")
    task = unreal.AssetImportTask()
    task.set_editor_property("filename", png)
    task.set_editor_property("destination_path", folder)
    task.set_editor_property("destination_name", name)
    task.set_editor_property("replace_existing", True)
    task.set_editor_property("automated", True)
    task.set_editor_property("save", False)
    unreal.AssetToolsHelpers.get_asset_tools().import_asset_tasks([task])
    texture = unreal.EditorAssetLibrary.load_asset(asset_path)
    if texture is None:
        raise AtlasError(f"The import did not create {asset_path}.")
    texture.set_editor_property("compression_settings", unreal.TextureCompressionSettings.TC_VECTOR_DISPLACEMENTMAP)
    texture.set_editor_property("srgb", False)
    texture.set_editor_property("address_x", unreal.TextureAddress.TA_CLAMP)
    texture.set_editor_property("address_y", unreal.TextureAddress.TA_CLAMP)
    texture.set_editor_property("lod_group", unreal.TextureGroup.TEXTUREGROUP_WORLD)
    texture.set_editor_property("lod_bias", 0)
    texture.set_editor_property("mip_gen_settings", unreal.TextureMipGenSettings.TMGS_SIMPLE_AVERAGE)
    # The streamer underestimates the mips M_TextRows needs (it samples small atlas cells), so distant
    # text shows broken low-mip MSDF until the player walks close. UEFN refuses Never Stream on save.
    texture.set_editor_property("global_force_mip_levels_to_be_resident", True)
    if widths:
        unreal.EditorAssetLibrary.set_metadata_tag(texture, WIDTHS_TAG, json.dumps(widths))
    unreal.EditorAssetLibrary.save_asset(asset_path, only_if_is_dirty=False)
    return asset_path


def parse_line(text):
    codes, icons, unknown = [], [], []
    style, i = 0, 0
    while i < len(text):
        tag = next((t for t in STYLE_TAGS if text.startswith(t[0], i)), None)
        if tag:
            style = tag[1]
            i += len(tag[0])
            continue
        tag = next((t for t in ICON_TAGS if text.startswith(t[0], i)), None)
        if tag:
            icons.append((tag[1], len(codes) + 1))
            codes.append(CODE_SPACE)
            i += len(tag[0])
            continue
        code = GLYPHS.find(text[i])
        if code < 0:
            unknown.append(text[i])
            codes.append(CODE_SPACE)
        else:
            codes.append(code + STYLE_OFFSET * style)
        i += 1
    truncated = len(codes) > MAX_CHARS
    return (codes + [CODE_EMPTY] * MAX_CHARS)[:MAX_CHARS], [ic for ic in icons if ic[1] <= MAX_CHARS], truncated, unknown


def layout_row(codes, icon_slots, widths, fit, slots_per_cell):
    scale = 1.0 / fit if fit > 0 else 1.0
    icon_width = 1.0 / slots_per_cell if slots_per_cell > 0 else 1.0
    starts, x, count = [], 0.0, 0
    for index, code in enumerate(codes):
        starts.append(x)
        if code >= 0:
            count = index + 1
            if index + 1 in icon_slots:
                x += icon_width
            else:
                x += (widths[code % STYLE_OFFSET] + PROP_PADDING) * scale
    return starts, x, count


def icon_offset(starts, end, count, slot, slots_per_cell, align):
    width = end * slots_per_cell
    shift = (width - count) * 0.5 * (1.0 + align)
    k = slot - 1
    if k < 0:
        return -shift
    if k >= count:
        return width - shift - count
    following = starts[k + 1] if k + 1 < len(starts) else end
    centre = (starts[k] + following) * 0.5 * slots_per_cell
    return (centre - shift) - (k + 0.5)


def centered_offset(index, count):
    return ROWS_CENTER + ((count - 1) * 0.5 - index) * ROW_PITCH


def asset_path_of(text):
    path = str(text or "").strip().strip("'\"")
    if "'" in path:
        path = path.split("'")[1]
    return path.split(".")[0]


def selected_instance():
    for asset in unreal.EditorUtilityLibrary.get_selected_assets():
        if isinstance(asset, unreal.MaterialInstanceConstant):
            texture = unreal.MaterialEditingLibrary.get_material_instance_texture_parameter_value(asset, "Atlas")
            return asset.get_path_name().split(".")[0], texture.get_path_name().split(".")[0] if texture else ""
    return "", ""


def list_atlases(hint=""):
    root = project_root(hint)
    found = []
    for item in unreal.EditorAssetLibrary.list_assets(root, recursive=True, include_folder=False):
        path = str(item).split(".")[0]
        name = path.rsplit("/", 1)[-1]
        if name.startswith("Text_Atlas_MSDF_"):
            found.append(path)
    found.sort(key=lambda p: p.rsplit("/", 1)[-1].lower())
    return found


def instance_widths(instance):
    texture = unreal.MaterialEditingLibrary.get_material_instance_texture_parameter_value(instance, "Atlas")
    name = texture.get_name() if texture else "(no atlas)"
    if texture:
        tag = unreal.EditorAssetLibrary.get_metadata_tag(texture, WIDTHS_TAG)
        if tag:
            try:
                values = [float(v) for v in json.loads(tag)]
                if len(values) == GRID * GRID:
                    return values, name, True
            except Exception:
                pass
    return list(FALLBACK_WIDTHS), name, False


def apply_scalars(instance, values):
    try:
        current = list(instance.get_editor_property("scalar_parameter_values"))
        left = dict(values)
        for item in current:
            name = str(item.get_editor_property("parameter_info").get_editor_property("name"))
            if name in left:
                item.set_editor_property("parameter_value", left.pop(name))
        for name, value in left.items():
            info = unreal.MaterialParameterInfo()
            info.set_editor_property("name", name)
            info.set_editor_property("association", unreal.MaterialParameterAssociation.GLOBAL_PARAMETER)
            info.set_editor_property("index", -1)
            item = unreal.ScalarParameterValue()
            item.set_editor_property("parameter_info", info)
            item.set_editor_property("parameter_value", value)
            current.append(item)
        instance.set_editor_property("scalar_parameter_values", current)
        probe = next(iter(values))
        return abs(float(unreal.MaterialEditingLibrary.get_material_instance_scalar_parameter_value(instance, probe)) - values[probe]) < 1e-6
    except Exception as exc:
        log(f"Batch parameter write failed, falling back: {exc}", warning=True)
        return False


def write_text(request):
    lib = unreal.MaterialEditingLibrary
    path = asset_path_of(request.get("instance"))
    instance = unreal.EditorAssetLibrary.load_asset(path) if path else None
    if not isinstance(instance, unreal.MaterialInstanceConstant):
        raise AtlasError(f"{path or 'Nothing'} is not a material instance.")
    names = set(str(n) for n in lib.get_scalar_parameter_names(instance))
    if not {"Row1_01", "Row1_PosEnd", "Icon1_PropOffsetX"} <= names:
        raise AtlasError("This instance is not a DynamicText material (Row1_01, Row1_PosEnd or Icon1_PropOffsetX is missing).")
    closed = False
    try:
        unreal.get_editor_subsystem(unreal.AssetEditorSubsystem).close_all_editors_for_asset(instance)
        closed = True
    except Exception as exc:
        log(f"Could not close the instance's editor: {exc}", warning=True)
    lines = write_text_into(request, instance, path, lib)
    if closed:
        lines.append(("info", "If this instance was open in the material editor it was closed, so its stale copy "
                              "cannot overwrite the new values. Reopen it to see them."))
    else:
        lines.append(("warn", "Could not close the instance's editor. If it is open, close and reopen it before "
                              "changing anything there, or it will overwrite the new values."))
    return lines


def write_text_into(request, instance, path, lib):
    pending = {}
    changed = [0, 0]

    def get(name):
        if name in pending:
            return pending[name]
        return float(lib.get_material_instance_scalar_parameter_value(instance, name))

    def put(name, value):
        if abs(get(name) - float(value)) > 1e-6:
            pending[name] = float(value)

    def switch(name, value):
        if bool(lib.get_material_instance_static_switch_parameter_value(instance, name)) != value:
            lib.set_material_instance_static_switch_parameter_value(instance, name, value)
            changed[1] += 1

    mode = request.get("mode", "Monospace")
    proportional = mode == "Proportional"
    switch("ProportionalSpacing", proportional)
    switch("GlyphOverlap", mode == "Overlap")
    font_note = None
    wanted = asset_path_of(request.get("atlas"))
    if wanted:
        current = lib.get_material_instance_texture_parameter_value(instance, "Atlas")
        if not current or current.get_path_name().split(".")[0] != wanted:
            texture = unreal.EditorAssetLibrary.load_asset(wanted)
            if not isinstance(texture, unreal.Texture):
                raise AtlasError(f"{wanted} is not a texture.")
            lib.set_material_instance_texture_parameter_value(instance, "Atlas", texture)
            changed[1] += 1
            font_note = ("ok", f"Font changed to {texture.get_name()}")
    widths, atlas, exact = instance_widths(instance)
    fit = get("GlyphFitX")
    rows = (list(request.get("rows") or []) + [{}] * MAX_ROWS)[:MAX_ROWS]
    active = [i for i, row in enumerate(rows) if row.get("text")]
    lines = [("ok", f"{path}  ·  {mode} spacing")]
    if font_note:
        lines.append(font_note)
    if not exact and not proportional:
        lines.append(("warn", f"{atlas} has no glyph widths stored. If it is an old 7x7 atlas it will not render correctly on this material."))
    if proportional:
        lines.append(("ok", f"Glyph widths from {atlas}") if exact else
                     ("warn", f"{atlas} has no glyph widths stored; using the average table. Regenerate the atlas with this tool for exact spacing."))
    layouts = {}
    placed = set()
    for r, row in enumerate(rows, 1):
        text = row.get("text", "")
        align = float(row.get("align", 0.0))
        codes, icons, truncated, unknown = parse_line(text)
        for slot, code in enumerate(codes, 1):
            put(f"Row{r}_{slot:02d}", code)
        put(f"Row{r}_Align", align)
        if request.get("center", True):
            put(f"Row{r}_VerticalOffset", centered_offset(active.index(r - 1), len(active)) if r - 1 in active
                else centered_offset(r - 1, MAX_ROWS))
        spacing = get(f"Row{r}_Spacing")
        per_cell = get(f"Row{r}_ScaleX") / spacing if spacing > 0 else 1.0
        if proportional:
            starts, end, count = layout_row(codes, [s for _, s in icons], widths, fit, per_cell)
            for slot, start in enumerate(starts, 1):
                put(f"Row{r}_Pos{slot:02d}", start)
            put(f"Row{r}_PosEnd", end)
            layouts[r] = (starts, end, count, per_cell, align)
        else:
            put(f"Row{r}_PosEnd", -1.0)
        for icon, slot in icons:
            put(f"Icon{icon}_Row", r)
            put(f"Icon{icon}_Slot", slot)
            put(f"Icon{icon}_Opacity", 1.0)
            placed.add(icon)
        if text:
            lines.append(("info", f"Row {r}: '{text}'"))
        if truncated:
            lines.append(("warn", f"Row {r} is longer than {MAX_CHARS} characters and was cut."))
        if unknown:
            lines.append(("warn", f"Row {r}: not in the atlas, drawn as spaces: " + " ".join(sorted(set(unknown)))))
    for icon in range(1, 4):
        r, slot = int(round(get(f"Icon{icon}_Row"))), int(round(get(f"Icon{icon}_Slot")))
        if r in layouts:
            starts, end, count, per_cell, align = layouts[r]
            put(f"Icon{icon}_PropOffsetX", icon_offset(starts, end, count, slot, per_cell, align))
        else:
            put(f"Icon{icon}_PropOffsetX", 0.0)
    if placed:
        lines.append(("info", "Icons placed from the text: " + ", ".join(f"Icon{i}" for i in sorted(placed))))
    changed[0] = len(pending)
    if not changed[0] and not changed[1]:
        lines.append(("ok", "Nothing changed; the instance already shows this text."))
        return lines
    if pending and not apply_scalars(instance, pending):
        for name, value in pending.items():
            lib.set_material_instance_scalar_parameter_value(instance, name, value)
        lines.append(("warn", "Batch write was not available; parameters were written one by one."))
    lib.update_material_instance(instance)
    unreal.EditorAssetLibrary.save_loaded_asset(instance, only_if_is_dirty=False)
    lines.append(("ok", f"Saved ({changed[0]} parameters changed"
                        + (", spacing mode switched - the instance recompiled" if changed[1] else "") + ")."))
    return lines


def write_json(path, data):
    tmp = path + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(data, f)
    os.replace(tmp, path)


def log(message, warning=False):
    text = f"[{APP_NAME}] {message}"
    if unreal is not None:
        (unreal.log_warning if warning else unreal.log)(text)


class UIThread:
    def __init__(self, bridge_folder):
        self.pid = "editor thread"
        self.thread = threading.Thread(target=self.run, args=(bridge_folder,), name="DynamicTextStudioUI", daemon=True)
        self.thread.start()

    def run(self, bridge_folder):
        try:
            run_ui(bridge_folder, in_editor=True)
        except Exception:
            log("The window stopped with an error:\n" + traceback.format_exc(), warning=True)

    def poll(self):
        return None if self.thread.is_alive() else 0


class EditorBridge:
    def __init__(self, process):
        self.process = process
        self.last_poll = 0.0
        self.last_beat = 0.0
        self.handle = unreal.register_slate_post_tick_callback(self.tick)

    def tick(self, _delta):
        now = time.time()
        if now - self.last_poll < 0.25:
            return
        self.last_poll = now
        try:
            if self.process.poll() is not None:
                self.stop()
                return
            if now - self.last_beat > 2.0:
                write_json(os.path.join(BRIDGE_DIR, "editor.json"), {"time": now})
                self.last_beat = now
            for request_path in glob.glob(os.path.join(BRIDGE_DIR, "req_*.json")):
                try:
                    request = json.load(open(request_path, encoding="utf-8"))
                except Exception:
                    continue
                os.remove(request_path)
                try:
                    response = self.handle_request(request)
                except Exception as exc:
                    log(f"Request failed: {exc}", warning=True)
                    response = {"ok": False, "error": str(exc)}
                write_json(os.path.join(BRIDGE_DIR, f"res_{request.get('id')}.json"), response)
        except Exception as exc:
            log(f"Bridge error: {exc}", warning=True)

    def handle_request(self, request):
        kind = request.get("type")
        if kind == "import":
            asset = import_texture(request["png"], request["folder"], request["name"], bool(request.get("replace")),
                                   request.get("widths"))
            log(f"Imported {asset}")
            return {"ok": True, "asset": asset}
        if kind == "selected_instance":
            instance, atlas = selected_instance()
            return {"ok": True, "instance": instance, "atlas": atlas}
        if kind == "list_atlases":
            return {"ok": True, "atlases": list_atlases(request.get("hint", ""))}
        if kind == "write_text":
            lines = write_text(request)
            log(f"Text written to {asset_path_of(request.get('instance'))}")
            return {"ok": True, "lines": lines}
        if kind == "content_browser_folder":
            return {"ok": True, "folder": content_browser_folder()}
        if kind == "list_folders":
            return dict(list_folders(request.get("path", ""), request.get("hint", "")), ok=True)
        if kind == "make_folder":
            return {"ok": True, "folder": make_folder(request.get("path", ""))}
        return {"ok": False, "error": f"Unknown request: {kind}"}

    def stop(self):
        if self.handle is not None:
            unreal.unregister_slate_post_tick_callback(self.handle)
            self.handle = None
        try:
            os.remove(os.path.join(BRIDGE_DIR, "editor.json"))
        except Exception:
            pass
        builtins.__dict__.pop(STATE_KEY, None)
        log("Window closed.")


def find_pythonw():
    candidates = [os.path.join(sys.base_prefix, "pythonw.exe"), os.path.join(sys.prefix, "pythonw.exe")]
    try:
        engine = unreal.Paths.convert_relative_path_to_full(unreal.Paths.engine_dir())
        candidates.append(os.path.join(engine, "Binaries", "ThirdParty", "Python3", "Win64", "pythonw.exe"))
    except Exception:
        pass
    candidates.append(r"C:\Program Files\Epic Games\Fortnite\Engine\Binaries\ThirdParty\Python3\Win64\pythonw.exe")
    for candidate in candidates:
        if candidate and os.path.isfile(candidate):
            return candidate
    raise AtlasError("Could not find UEFN's pythonw.exe.")


def launch_in_uefn():
    state = builtins.__dict__.get(STATE_KEY)
    if state is not None and state.process.poll() is None:
        log("The window is already open.", warning=True)
        return
    os.makedirs(BRIDGE_DIR, exist_ok=True)
    for old in glob.glob(os.path.join(BRIDGE_DIR, "*.json")):
        try:
            os.remove(old)
        except Exception:
            pass
    write_json(os.path.join(BRIDGE_DIR, "editor.json"), {"time": time.time()})
    try:
        import tkinter
        process = UIThread(BRIDGE_DIR)
    except ImportError as exc:
        log(f"tkinter is not available in the editor ({exc}); opening the window as a separate process.", warning=True)
        env = dict(os.environ)
        for var in ("PYTHONHOME", "PYTHONPATH", "PYTHONSTARTUP"):
            env.pop(var, None)
        script = os.path.abspath(__file__)
        process = subprocess.Popen([find_pythonw(), script, "--ui", "--bridge", BRIDGE_DIR],
                                   cwd=os.path.dirname(script), env=env)
    builtins.__dict__[STATE_KEY] = EditorBridge(process)
    log(f"Window opened (pid {process.pid}).")


class Bridge:
    def __init__(self, folder):
        self.folder = folder

    def alive(self):
        if not self.folder:
            return False
        try:
            beat = json.load(open(os.path.join(self.folder, "editor.json"), encoding="utf-8"))
            return time.time() - beat.get("time", 0) < 10
        except Exception:
            return False

    def request(self, payload, timeout=120.0):
        request_id = uuid.uuid4().hex
        write_json(os.path.join(self.folder, f"req_{request_id}.json"), dict(payload, id=request_id))
        response_path = os.path.join(self.folder, f"res_{request_id}.json")
        deadline = time.time() + timeout
        while time.time() < deadline:
            if os.path.exists(response_path):
                try:
                    response = json.load(open(response_path, encoding="utf-8"))
                except Exception:
                    time.sleep(0.1)
                    continue
                try:
                    os.remove(response_path)
                except Exception:
                    pass
                return response
            time.sleep(0.2)
        return {"ok": False, "error": "UEFN did not respond. Is the tool still running in the editor?"}


def run_ui(bridge_folder, in_editor=False):
    import tkinter as tk
    from tkinter import filedialog

    if not in_editor:
        try:
            import ctypes
            ctypes.windll.shcore.SetProcessDpiAwareness(1)
        except Exception:
            pass

    C = {
        "bg": "#15161a", "card": "#1f2127", "field": "#2a2d35", "field_hover": "#323641", "border": "#343844",
        "text": "#eceef2", "muted": "#9aa1ad", "faint": "#6b7280", "accent": "#5b8cff", "accent_hover": "#77a0ff",
        "accent_dim": "#3a4f80", "ok": "#3ecf8e", "warn": "#f5a524", "error": "#f25f5c", "track": "#2a2d35",
    }
    FONT = "Segoe UI"

    def rounded(canvas, x0, y0, x1, y1, r, **kw):
        points = [x0 + r, y0, x1 - r, y0, x1, y0, x1, y0 + r, x1, y1 - r, x1, y1, x1 - r, y1,
                  x0 + r, y1, x0, y1, x0, y1 - r, x0, y0 + r, x0, y0]
        return canvas.create_polygon(points, smooth=True, **kw)

    class Button(tk.Canvas):
        def __init__(self, parent, text, command, kind="secondary", width=160, height=36, bg=None):
            super().__init__(parent, width=width, height=height, bg=bg or C["card"], highlightthickness=0, cursor="hand2")
            self.text, self.command, self.kind = text, command, kind
            self.enabled, self.hover = True, False
            self.bind("<Enter>", lambda e: self._set_hover(True))
            self.bind("<Leave>", lambda e: self._set_hover(False))
            self.bind("<ButtonRelease-1>", lambda e: self.enabled and self.command())
            self.bind("<Configure>", lambda e: self.draw())
            self.draw()

        def _set_hover(self, value):
            self.hover = value
            self.draw()

        def set_enabled(self, value):
            self.enabled = value
            self.configure(cursor="hand2" if value else "arrow")
            self.draw()

        def set_text(self, text):
            self.text = text
            self.draw()

        def draw(self):
            self.delete("all")
            w, h = self.winfo_width() or int(self["width"]), self.winfo_height() or int(self["height"])
            if self.kind == "primary":
                fill = C["accent_hover"] if self.hover and self.enabled else C["accent"]
                if not self.enabled:
                    fill = C["accent_dim"]
                fg = "#ffffff"
                size = 11
            else:
                fill = C["field_hover"] if self.hover and self.enabled else C["field"]
                fg = C["text"] if self.enabled else C["faint"]
                size = 10
            rounded(self, 1, 1, w - 1, h - 1, 10, fill=fill, outline="")
            self.create_text(w / 2, h / 2, text=self.text, fill=fg, font=(FONT, size, "bold" if self.kind == "primary" else "normal"))

    class Toggle(tk.Canvas):
        def __init__(self, parent, text, variable, command=None):
            super().__init__(parent, height=28, bg=C["card"], highlightthickness=0, cursor="hand2")
            self.text, self.variable, self.command, self.enabled = text, variable, command, True
            self.bind("<ButtonRelease-1>", self._toggle)
            self.bind("<Configure>", lambda e: self.draw())
            variable.trace_add("write", lambda *a: self.draw())
            self.draw()

        def _toggle(self, _event):
            if self.enabled:
                self.variable.set(not self.variable.get())
                if self.command:
                    self.command()

        def set_enabled(self, value):
            self.enabled = value
            self.configure(cursor="hand2" if value else "arrow")
            self.draw()

        def draw(self):
            self.delete("all")
            on = bool(self.variable.get())
            track = C["accent"] if on and self.enabled else (C["accent_dim"] if on else C["field"])
            rounded(self, 2, 5, 40, 23, 9, fill=track, outline="")
            knob_x = 31 if on else 13
            self.create_oval(knob_x - 7, 7, knob_x + 7, 21, fill="#ffffff" if self.enabled else "#9aa1ad", outline="")
            self.create_text(52, 14, text=self.text, anchor="w", fill=C["text"] if self.enabled else C["faint"], font=(FONT, 10))

    class Dropdown(tk.Canvas):
        def __init__(self, parent, on_select=None):
            super().__init__(parent, height=36, bg=C["card"], highlightthickness=0, cursor="hand2")
            self.values, self.index, self.enabled, self.hover = [], -1, False, False
            self.on_select = on_select
            self.bind("<Enter>", lambda e: self._set_hover(True))
            self.bind("<Leave>", lambda e: self._set_hover(False))
            self.bind("<ButtonRelease-1>", self._open)
            self.bind("<Configure>", lambda e: self.draw())
            self.draw()

        def _set_hover(self, value):
            self.hover = value
            self.draw()

        def set_values(self, values):
            self.values = list(values)
            self.index = 0 if self.values else -1
            self.draw()

        def current(self, index=None):
            if index is not None:
                self.index = index if 0 <= index < len(self.values) else -1
                self.draw()
            return self.index

        def set(self, value):
            self.index = self.values.index(value) if value in self.values else -1
            self.draw()

        def get(self):
            return self.values[self.index] if 0 <= self.index < len(self.values) else ""

        def set_enabled(self, value):
            self.enabled = value
            self.configure(cursor="hand2" if value else "arrow")
            self.draw()

        def _open(self, _event):
            if not self.enabled or not self.values:
                return
            menu = tk.Menu(self, tearoff=0, bg=C["field"], fg=C["text"], activebackground=C["accent"],
                           activeforeground="#ffffff", bd=0, relief="flat", font=(FONT, 10))
            for i, value in enumerate(self.values):
                menu.add_command(label=("✓  " if i == self.index else "     ") + value,
                                 command=lambda i=i: self._choose(i))
            menu.tk_popup(self.winfo_rootx(), self.winfo_rooty() + self.winfo_height() + 2)

        def _choose(self, index):
            self.index = index
            self.draw()
            if self.on_select:
                self.on_select()

        def draw(self):
            self.delete("all")
            w, h = self.winfo_width() or 200, self.winfo_height() or 36
            fill = C["field_hover"] if self.hover and self.enabled else C["field"]
            if not self.enabled:
                fill = C["card"]
            rounded(self, 1, 1, w - 1, h - 1, 9, fill=fill, outline=C["border"] if not self.enabled else "")
            text = self.get() or "—"
            self.create_text(12, h / 2, text=text, anchor="w", fill=C["text"] if self.enabled else C["faint"], font=(FONT, 10))
            cx, cy = w - 18, h / 2
            self.create_line(cx - 5, cy - 2, cx, cy + 3, cx + 5, cy - 2, fill=C["muted"] if self.enabled else C["border"], width=2)

    class Progress(tk.Canvas):
        def __init__(self, parent):
            super().__init__(parent, height=6, bg=C["bg"], highlightthickness=0)
            self.value = 0.0
            self.bind("<Configure>", lambda e: self.draw())

        def set(self, value):
            self.value = max(0.0, min(1.0, value))
            self.draw()

        def draw(self):
            self.delete("all")
            w = self.winfo_width()
            rounded(self, 0, 0, w, 6, 3, fill=C["track"], outline="")
            if self.value > 0:
                rounded(self, 0, 0, max(6, w * self.value), 6, 3, fill=C["accent"], outline="")

    class Pill(tk.Canvas):
        def __init__(self, parent):
            super().__init__(parent, width=230, height=30, bg=C["bg"], highlightthickness=0)
            self.set("Checking UEFN...", C["muted"])

        def set(self, text, color):
            self.delete("all")
            rounded(self, 1, 1, 229, 29, 14, fill=C["card"], outline=C["border"])
            self.create_oval(14, 11, 22, 19, fill=color, outline="")
            self.create_text(32, 15, text=text, anchor="w", fill=C["text"], font=(FONT, 9))

    def card(parent, title, subtitle=None):
        outer = tk.Frame(parent, bg=C["card"], highlightthickness=1, highlightbackground=C["border"])
        head = tk.Frame(outer, bg=C["card"])
        head.pack(fill="x", padx=16, pady=(14, 6))
        tk.Label(head, text=title, bg=C["card"], fg=C["text"], font=(FONT, 11, "bold")).pack(side="left")
        if subtitle:
            tk.Label(head, text=subtitle, bg=C["card"], fg=C["faint"], font=(FONT, 9)).pack(side="left", padx=8)
        body = tk.Frame(outer, bg=C["card"])
        body.pack(fill="both", expand=True, padx=16, pady=(0, 14))
        return outer, body

    def label(parent, text):
        return tk.Label(parent, text=text, bg=C["card"], fg=C["muted"], font=(FONT, 9))

    def entry(parent, variable):
        frame = tk.Frame(parent, bg=C["field"], highlightthickness=1, highlightbackground=C["field"], highlightcolor=C["accent"])
        widget = tk.Entry(frame, textvariable=variable, bg=C["field"], fg=C["text"], insertbackground=C["text"],
                          relief="flat", font=(FONT, 10), borderwidth=0)
        widget.pack(fill="x", padx=10, pady=7)
        widget.bind("<FocusIn>", lambda e: frame.configure(highlightbackground=C["accent"]))
        widget.bind("<FocusOut>", lambda e: frame.configure(highlightbackground=C["field"]))
        return frame, widget

    def make_icon(size=32):
        glyph = [".###.", "#...#", "#...#", "#####", "#...#", "#...#", "#...#"]
        image = tk.PhotoImage(width=size, height=size)
        scale = 3
        gx, gy = (size - 5 * scale) // 2, (size - 7 * scale) // 2
        radius = 7
        rows = []
        outside = []
        for y in range(size):
            row = []
            for x in range(size):
                cx = min(max(x, radius), size - 1 - radius)
                cy = min(max(y, radius), size - 1 - radius)
                if (x - cx) ** 2 + (y - cy) ** 2 > radius ** 2:
                    outside.append((x, y))
                    row.append(C["bg"])
                    continue
                lx, ly = (x - gx) // scale, (y - gy) // scale
                if 0 <= x - gx < 5 * scale and 0 <= y - gy < 7 * scale and glyph[ly][lx] == "#":
                    row.append("#ffd23c")
                else:
                    row.append(C["accent"])
            rows.append("{" + " ".join(row) + "}")
        image.put(" ".join(rows))
        for x, y in outside:
            image.transparency_set(x, y, True)
        return image

    def center_on(window, parent, width, height):
        parent.update_idletasks()
        x = parent.winfo_rootx() + (parent.winfo_width() - width) // 2
        y = parent.winfo_rooty() + (parent.winfo_height() - height) // 3
        window.geometry(f"{width}x{height}+{max(x, 0)}+{max(y, 0)}")

    def show_dialog(parent, title, message, kind="info", prompt=None, ok_text="OK"):
        window = tk.Toplevel(parent)
        window.title(title)
        window.configure(bg=C["bg"])
        window.transient(parent)
        window.resizable(False, False)
        colors = {"info": C["accent"], "error": C["error"], "warn": C["warn"], "ok": C["ok"]}
        body = tk.Frame(window, bg=C["card"], highlightthickness=1, highlightbackground=C["border"])
        body.pack(fill="both", expand=True, padx=14, pady=14)
        head = tk.Frame(body, bg=C["card"])
        head.pack(fill="x", padx=18, pady=(16, 6))
        dot = tk.Canvas(head, width=12, height=12, bg=C["card"], highlightthickness=0)
        dot.create_oval(1, 1, 11, 11, fill=colors.get(kind, C["accent"]), outline="")
        dot.pack(side="left", padx=(0, 10))
        tk.Label(head, text=title, bg=C["card"], fg=C["text"], font=(FONT, 11, "bold")).pack(side="left")
        tk.Label(body, text=message, bg=C["card"], fg=C["muted"], font=(FONT, 10), justify="left",
                 wraplength=400, anchor="w").pack(fill="x", padx=18)
        value = tk.StringVar(value=prompt or "")
        field_widget = None
        if prompt is not None:
            field, field_widget = entry(body, value)
            field.pack(fill="x", padx=18, pady=(12, 0))
        result = {"value": None}

        def accept(_event=None):
            result["value"] = value.get().strip() if prompt is not None else True
            window.destroy()

        buttons = tk.Frame(body, bg=C["card"])
        buttons.pack(fill="x", padx=18, pady=16)
        Button(buttons, ok_text, accept, kind="primary", width=110, height=34).pack(side="right")
        if prompt is not None:
            Button(buttons, "Cancel", window.destroy, width=100, height=34).pack(side="right", padx=(0, 8))
        window.bind("<Return>", accept)
        window.bind("<Escape>", lambda e: window.destroy())
        center_on(window, parent, 480, 250 if prompt is not None else 200)
        window.grab_set()
        if field_widget is not None:
            field_widget.focus_set()
            field_widget.select_range(0, "end")
        parent.wait_window(window)
        return result["value"]

    class FolderPicker:
        def __init__(self, app, start):
            self.app, self.bridge = app, app.bridge
            self.result, self.path, self.root_path, self.folders = None, start, "", []
            self.queue = queue.Queue()
            self.window = window = tk.Toplevel(app.root)
            window.title("Choose content folder")
            window.configure(bg=C["bg"])
            window.transient(app.root)
            window.minsize(520, 480)
            head = tk.Frame(window, bg=C["bg"])
            head.pack(fill="x", padx=20, pady=(18, 10))
            tk.Label(head, text="Choose a content folder", bg=C["bg"], fg=C["text"], font=(FONT, 14, "bold")).pack(anchor="w")
            tk.Label(head, text="Folders from the project open in UEFN", bg=C["bg"], fg=C["muted"], font=(FONT, 9)).pack(anchor="w")
            outer = tk.Frame(window, bg=C["card"], highlightthickness=1, highlightbackground=C["border"])
            outer.pack(fill="both", expand=True, padx=20)
            bar = tk.Frame(outer, bg=C["card"])
            bar.pack(fill="x", padx=12, pady=12)
            self.up_button = Button(bar, "↑  Up", self.go_up, width=80, height=32)
            self.up_button.pack(side="left")
            self.path_label = tk.Label(bar, text="", bg=C["card"], fg=C["text"], font=(FONT, 10, "bold"), anchor="w")
            self.path_label.pack(side="left", fill="x", expand=True, padx=12)
            self.listbox = tk.Listbox(outer, bg=C["field"], fg=C["text"], selectbackground=C["accent"],
                                      selectforeground="#ffffff", highlightthickness=0, borderwidth=0, relief="flat",
                                      activestyle="none", font=(FONT, 11))
            self.listbox.pack(fill="both", expand=True, padx=12)
            self.listbox.bind("<Double-Button-1>", self.open_selected)
            self.listbox.bind("<Return>", self.open_selected)
            self.status = tk.Label(outer, text="", bg=C["card"], fg=C["faint"], font=(FONT, 9), anchor="w")
            self.status.pack(fill="x", padx=12, pady=(8, 12))
            buttons = tk.Frame(window, bg=C["bg"])
            buttons.pack(fill="x", padx=20, pady=16)
            Button(buttons, "New Folder", self.new_folder, width=120, height=36, bg=C["bg"]).pack(side="left")
            Button(buttons, "Content Browser Folder", self.go_content_browser, width=190, height=36, bg=C["bg"]).pack(side="left", padx=(8, 0))
            Button(buttons, "Select", self.select, kind="primary", width=110, height=36, bg=C["bg"]).pack(side="right")
            Button(buttons, "Cancel", window.destroy, width=100, height=36, bg=C["bg"]).pack(side="right", padx=(0, 8))
            window.bind("<Escape>", lambda e: window.destroy())
            center_on(window, app.root, 620, 600)
            window.grab_set()
            self.load(start)
            window.after(60, self.poll)
            app.root.wait_window(window)

        def request(self, payload, then):
            self.status.configure(text="Loading...")
            threading.Thread(target=lambda: self.queue.put((then, self.bridge.request(payload, timeout=15))), daemon=True).start()

        def poll(self):
            if not self.window.winfo_exists():
                return
            try:
                while True:
                    handler, response = self.queue.get_nowait()
                    handler(response)
            except queue.Empty:
                pass
            self.window.after(60, self.poll)

        def load(self, path):
            self.request({"type": "list_folders", "path": path, "hint": self.app.folder_var.get()}, self.show)

        def show(self, response):
            if not response.get("ok"):
                self.status.configure(text=response.get("error") or "Could not list folders.", fg=C["error"])
                return
            self.path, self.root_path, self.folders = response["path"], response["root"], response["folders"]
            self.path_label.configure(text=self.path)
            self.up_button.set_enabled(self.path != self.root_path)
            self.listbox.delete(0, "end")
            for folder in self.folders:
                self.listbox.insert("end", "   ▸   " + folder.rsplit("/", 1)[-1])
            count = len(self.folders)
            self.status.configure(fg=C["faint"], text="No subfolders. Select to use this folder." if count == 0 else
                                  f"{count} subfolder{'s' if count != 1 else ''}. Double-click to open, Select to use the highlighted or current folder.")

        def open_selected(self, _event=None):
            selection = self.listbox.curselection()
            if selection:
                self.load(self.folders[selection[0]])

        def go_up(self):
            if self.path != self.root_path:
                self.load(self.path.rsplit("/", 1)[0] or self.root_path)

        def go_content_browser(self):
            def jump(response):
                if response.get("ok") and response.get("folder"):
                    self.load(response["folder"])
                else:
                    self.status.configure(text=response.get("error") or "The Content Browser folder is not available.", fg=C["error"])
            self.request({"type": "content_browser_folder"}, jump)

        def new_folder(self):
            name = show_dialog(self.window, "New folder", f"Create a folder inside {self.path}", prompt="NewFolder", ok_text="Create")
            if not name:
                return
            clean = re.sub(r"[^A-Za-z0-9_ -]", "", name).strip()
            if not clean:
                show_dialog(self.window, "Invalid name", "Use letters, numbers, spaces, - or _.", kind="error")
                return

            def created(response):
                if response.get("ok"):
                    self.load(response["folder"])
                else:
                    self.status.configure(text=response.get("error") or "Could not create the folder.", fg=C["error"])
            self.request({"type": "make_folder", "path": f"{self.path}/{clean}"}, created)

        def select(self):
            selection = self.listbox.curselection()
            self.result = self.folders[selection[0]] if selection else self.path
            self.window.destroy()

    class App:
        def __init__(self):
            self.bridge = Bridge(bridge_folder)
            self.root = tk.Tk()
            self.root.title(f"{APP_NAME} {APP_VERSION}")
            self.icon = make_icon()
            self.root.iconphoto(True, self.icon)
            self.root.configure(bg=C["bg"])
            self.root.geometry("1280x900")
            self.root.minsize(1200, 860)
            self.events = queue.Queue()
            self.busy = False
            self.name_edited = False
            self.preview_image = None
            self.connected = False
            self.settings = self.load_settings()
            self.build()
            self.root.after(100, self.poll_events)
            self.root.after(300, self.check_bridge)

        def load_settings(self):
            for path in (SETTINGS_PATH, LEGACY_SETTINGS_PATH):
                try:
                    return json.load(open(path, encoding="utf-8-sig"))
                except Exception:
                    pass
            return {}

        def save_settings(self):
            data = dict(self.settings)
            data.update({"font": self.font_var.get(), "folder": self.folder_var.get(),
                         "replace": bool(self.replace_var.get())})
            if hasattr(self, "row_vars"):
                data.update({"instance": self.instance_var.get(), "mode": self.mode_var.get(), "atlas": self.chosen_atlas(),
                             "center": bool(self.center_var.get()), "tab": self.tab,
                             "rows": [v.get() for v in self.row_vars], "aligns": [v.get() for v in self.align_vars]})
            self.settings = data
            try:
                os.makedirs(DATA_ROOT, exist_ok=True)
                json.dump(data, open(SETTINGS_PATH, "w", encoding="utf-8"), indent=2)
            except Exception:
                pass

