        def show_tab(self, key):
            if key == self.tab:
                return
            self.tab = key
            for name, button in self.tab_buttons.items():
                button.kind = "primary" if name == key else "secondary"
                button.draw()
            self.page_atlas.pack_forget()
            self.page_text.pack_forget()
            (self.page_atlas if key == "atlas" else self.page_text).pack(fill="both", expand=True)
            self.subtitle.configure(text="Multi-channel SDF glyph atlases for text materials" if key == "atlas"
                                    else "Write text into a DynamicText material instance")

        def segmented(self, parent, options, variable, width, height=34, on_change=None):
            frame = tk.Frame(parent, bg=C["card"])
            buttons = {}

            def refresh(*_):
                for value, button in buttons.items():
                    button.kind = "primary" if variable.get() == value else "secondary"
                    button.draw()

            def choose(value):
                variable.set(value)
                if on_change:
                    on_change()

            for text, value in options:
                button = Button(frame, text, lambda v=value: choose(v), width=width, height=height)
                button.pack(side="left", padx=(0, 6))
                buttons[value] = button
            variable.trace_add("write", refresh)
            refresh()
            return frame, list(buttons.values())

